import{A as e,E as t,d as n,f as r,l as i,p as a,s as o}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as s}from"./app-B7SOiXO-.js";var c=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/SQLServer/02_%E8%BF%9B%E9%98%B6%E7%AF%87/02_%E6%89%A7%E8%A1%8C%E8%AE%A1%E5%88%92%E6%B7%B1%E5%BA%A6%E8%A7%A3%E8%AF%BB.html","title":"执行计划深度解读","lang":"zh-CN","frontmatter":{"title":"执行计划深度解读","order":2,"category":["数据库","SQLServer"],"tag":["SQL Server","执行计划","查询优化","参数嗅探","Query Store"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":8.58,"words":2575},"filePathRelative":"后端开发/数据库/SQLServer/02_进阶篇/02_执行计划深度解读.md"}`),l={name:`02_执行计划深度解读.md`};function u(s,c,l,u,d,f){let p=e(`Mermaid`);return t(),i(`div`,null,[c[0]||=o(`h1`,{id:`执行计划深度解读`,tabindex:`-1`},[o(`a`,{class:`header-anchor`,href:`#执行计划深度解读`},[o(`span`,null,`执行计划深度解读`)])],-1),c[1]||=o(`blockquote`,null,[o(`p`,null,[o(`strong`,null,`读懂执行计划，就像拥有了 SQL Server 的 X 光机。`),r(` 不看执行计划的调优，等于蒙眼开车。`)])],-1),c[2]||=o(`hr`,null,null,-1),c[3]||=o(`h2`,{id:`一、查询优化管线`,tabindex:`-1`},[o(`a`,{class:`header-anchor`,href:`#一、查询优化管线`},[o(`span`,null,`一、查询优化管线`)])],-1),a(p,{code:``}),c[4]||=n(`<div class="hint-container important"><p class="hint-container-title">优化器是成本驱动的</p><p>SQL Server 优化器基于 <strong>成本估算（Cost-Based）</strong> 选择执行计划，而非&quot;最优&quot;。它依赖统计信息估算行数和成本，统计信息不准确时，可能选择次优计划。</p></div><hr><h2 id="二、核心算子解读" tabindex="-1"><a class="header-anchor" href="#二、核心算子解读"><span>二、核心算子解读</span></a></h2><h3 id="_2-1-扫描-vs-查找" tabindex="-1"><a class="header-anchor" href="#_2-1-扫描-vs-查找"><span>2.1 扫描 vs 查找</span></a></h3><table><thead><tr><th>算子</th><th>含义</th><th>成本</th><th>场景</th></tr></thead><tbody><tr><td><strong>Table Scan</strong></td><td>全表扫描</td><td>高</td><td>堆表无索引</td></tr><tr><td><strong>Clustered Index Scan</strong></td><td>聚集索引全扫</td><td>高</td><td>无合适索引</td></tr><tr><td><strong>Clustered Index Seek</strong></td><td>聚集索引查找</td><td>低</td><td>✅ 理想</td></tr><tr><td><strong>Non-Clustered Index Scan</strong></td><td>非聚集索引全扫</td><td>中</td><td>索引不够精确</td></tr><tr><td><strong>Non-Clustered Index Seek</strong></td><td>非聚集索引查找</td><td>低</td><td>✅ 理想</td></tr><tr><td><strong>Key Lookup</strong></td><td>回表查聚集索引</td><td>中高</td><td>非聚集索引未覆盖</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 演示 Seek vs Scan</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 没有索引 → Clustered Index Scan</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1001</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 创建非聚集索引 → Index Seek + Key Lookup</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> IX_Orders_CustomerId</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> Orders(CustomerId);</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1001</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 执行计划: Index Seek (IX_Orders_CustomerId) → Key Lookup (PK_Orders)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 覆盖索引 → 纯 Index Seek</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> IX_Orders_CustId_Cover</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> Orders(CustomerId)</span></span>
<span class="line"><span style="color:#C678DD;">INCLUDE</span><span style="color:#ABB2BF;"> (OrderDate, Amount);</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> CustomerId, OrderDate, Amount </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1001</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 执行计划: Index Seek（无 Key Lookup）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-连接算子" tabindex="-1"><a class="header-anchor" href="#_2-2-连接算子"><span>2.2 连接算子</span></a></h3><table><thead><tr><th>算子</th><th>最佳场景</th><th>复杂度</th><th>内存</th></tr></thead><tbody><tr><td><strong>Nested Loop Join</strong></td><td>小表驱动大表，有索引</td><td>O(N×M)</td><td>极少</td></tr><tr><td><strong>Hash Match Join</strong></td><td>大表×大表，无索引</td><td>O(N+M)</td><td>多</td></tr><tr><td><strong>Merge Join</strong></td><td>两个输入都已排序</td><td>O(N+M)</td><td>极少</td></tr></tbody></table>`,8),a(p,{code:``}),c[5]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Nested Loop：小表（10行）驱动大表（100万行），内表有索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerName</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers c  </span><span style="color:#7F848E;font-style:italic;">-- 小表：外表</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> Orders o </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#7F848E;font-style:italic;">  -- 大表：内表，CustomerId 有索引</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1001</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 10次 Index Seek，极快</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Hash Match：两个大表连接，无索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ProductName</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders o</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> OrderItems oi </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> oi</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> Products p </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> oi</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ProductId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ProductId</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderDate</span><span style="color:#56B6C2;"> &gt;=</span><span style="color:#98C379;"> &#39;2024-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 先对一个输入建哈希表，再逐行探测另一个输入</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Merge Join：两输入都已排序</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">od</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders o</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> OrderDetails od </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> od</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 如果两个输入都按 OrderId 排序，优化器选择 Merge Join</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-聚合与排序" tabindex="-1"><a class="header-anchor" href="#_2-3-聚合与排序"><span>2.3 聚合与排序</span></a></h3><table><thead><tr><th>算子</th><th>说明</th></tr></thead><tbody><tr><td><strong>Hash Aggregate</strong></td><td>哈希聚合，适合大数据量、无排序输入</td></tr><tr><td><strong>Stream Aggregate</strong></td><td>流聚合，输入已排序时可逐行累加，省内存</td></tr><tr><td><strong>Sort</strong></td><td>排序，可能溢出到 tempdb（Spill to TempDB）</td></tr><tr><td><strong>Spool</strong></td><td>缓存中间结果，避免重复计算</td></tr></tbody></table><hr><h2 id="三、set-statistics-io-time" tabindex="-1"><a class="header-anchor" href="#三、set-statistics-io-time"><span>三、SET STATISTICS IO / TIME</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 开启 I/O 和时间统计</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> STATISTICS</span><span style="color:#C678DD;"> IO</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> STATISTICS</span><span style="color:#C678DD;"> TIME</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerName</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Amount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders o</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> Customers c </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderDate</span><span style="color:#56B6C2;"> &gt;=</span><span style="color:#98C379;"> &#39;2024-01-01&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Amount</span><span style="color:#C678DD;"> DESC</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 输出示例：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- SQL Server 执行时间:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--    CPU 时间 = 15 ms，占用时间 = 12 ms</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 表 &#39;Orders&#39;。扫描计数 1，逻辑读取 42 次，物理读取 0 次，预读 0 次</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 表 &#39;Customers&#39;。扫描计数 1，逻辑读取 8 次，物理读取 0 次，预读 0 次</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>指标</th><th>含义</th><th>关注</th></tr></thead><tbody><tr><td>逻辑读取</td><td>从 Buffer Pool 读取的页数</td><td>✅ 最核心的指标</td></tr><tr><td>物理读取</td><td>从磁盘读取的页数</td><td>冷查询时关注</td></tr><tr><td>预读</td><td>预读到 Buffer Pool 的页数</td><td>大扫描时关注</td></tr><tr><td>扫描计数</td><td>访问表的次数</td><td>Nested Loop 时关注</td></tr><tr><td>CPU 时间</td><td>CPU 消耗</td><td>排序/哈希时关注</td></tr><tr><td>占用时间</td><td>实际耗时（含等待）</td><td>含锁等待等</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">调优看逻辑读取</p><p>逻辑读取是评价查询效率的最稳定指标——不受缓存状态影响。同样的查询，逻辑读取越少越好。</p></div><hr><h2 id="四、实际执行计划-vs-估算执行计划" tabindex="-1"><a class="header-anchor" href="#四、实际执行计划-vs-估算执行计划"><span>四、实际执行计划 vs 估算执行计划</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 估算执行计划（不实际执行）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- SSMS: Ctrl+L</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 不执行查询，只看优化器的估算</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 实际执行计划（执行后查看）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- SSMS: Ctrl+M</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> STATISTICS</span><span style="color:#C678DD;"> PROFILE</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1001</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 返回实际行数 vs 估算行数，差异大说明统计信息不准确</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>维度</th><th>估算计划</th><th>实际计划</th></tr></thead><tbody><tr><td>是否执行</td><td>❌</td><td>✅</td></tr><tr><td>行数</td><td>估算值</td><td>实际值</td></tr><tr><td>成本</td><td>估算值</td><td>实际 I/O/CPU</td></tr><tr><td>用途</td><td>开发时预览</td><td>性能诊断</td></tr><tr><td>可靠性</td><td>可能偏差大</td><td>✅ 真实</td></tr></tbody></table><hr><h2 id="五、参数嗅探-parameter-sniffing" tabindex="-1"><a class="header-anchor" href="#五、参数嗅探-parameter-sniffing"><span>五、参数嗅探（Parameter Sniffing）</span></a></h2><p>参数嗅探是 SQL Server 优化器根据第一次传入的参数值生成执行计划并缓存，后续不同参数复用同一计划——但不同参数可能需要不同的最优计划。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 场景：Orders 表 CustomerId 分布不均匀</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- CustomerId=1 有 100万订单，CustomerId=9999 只有 5 订单</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 第一次调用：CustomerId=9999（少量数据）</span></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#ABB2BF;"> sp_executesql</span></span>
<span class="line"><span style="color:#98C379;">    N&#39;SELECT * FROM Orders WHERE CustomerId = @CustId&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">    N&#39;@CustId INT&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">@CustId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 9999</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 优化器选择 Index Seek + Key Lookup（少量数据，回表划算）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 第二次调用：CustomerId=1（大量数据）</span></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#ABB2BF;"> sp_executesql</span></span>
<span class="line"><span style="color:#98C379;">    N&#39;SELECT * FROM Orders WHERE CustomerId = @CustId&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">    N&#39;@CustId INT&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">@CustId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 复用了上面的 Seek + Lookup 计划！</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 但 100万行回表比全表扫描更慢！</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 解决方案 1：OPTION (RECOMPILE) 每次重编译</span></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#ABB2BF;"> sp_executesql</span></span>
<span class="line"><span style="color:#98C379;">    N&#39;SELECT * FROM Orders WHERE CustomerId = @CustId OPTION (RECOMPILE)&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">    N&#39;@CustId INT&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">@CustId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 每次重新生成最优计划，代价是编译开销</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 解决方案 2：OPTION (OPTIMIZE FOR UNKNOWN)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#E06C75;"> @CustId</span></span>
<span class="line"><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (OPTIMIZE </span><span style="color:#C678DD;">FOR</span><span style="color:#ABB2BF;"> UNKNOWN);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 不使用参数值，用统计信息的平均值生成通用计划</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 解决方案 3：OPTION (OPTIMIZE FOR) 指定参数值</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#E06C75;"> @CustId</span></span>
<span class="line"><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (OPTIMIZE </span><span style="color:#C678DD;">FOR</span><span style="color:#ABB2BF;"> (</span><span style="color:#E06C75;">@CustId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 按指定值优化（适合已知典型参数分布）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 解决方案 4：本地变量&quot;去嗅探&quot;</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @LocalCustId</span><span style="color:#C678DD;"> INT</span><span style="color:#56B6C2;"> =</span><span style="color:#E06C75;"> @CustId</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#E06C75;"> @LocalCustId</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 本地变量不会被嗅探，优化器使用通用估算</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,16),a(p,{code:``}),c[6]||=n(`<div class="hint-container important"><p class="hint-container-title">参数嗅探是双刃剑</p><ul><li><strong>好处</strong>：避免每次编译，计划缓存复用效率高</li><li><strong>坏处</strong>：数据分布不均时，&quot;通用计划&quot;可能对某些参数很差</li><li><strong>判断方法</strong>：Query Store 的 Regressed Queries 报告</li></ul></div><hr><h2 id="六、query-store" tabindex="-1"><a class="header-anchor" href="#六、query-store"><span>六、Query Store</span></a></h2><p>SQL Server 2016+ 的 Query Store 是执行计划管理的革命性功能。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 启用 Query Store</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#ABB2BF;"> MyDB </span><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> QUERY_STORE</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#ABB2BF;"> MyDB </span><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> QUERY_STORE</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    OPERATION_MODE</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> READ_WRITE</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    MAX_STORAGE_SIZE_MB</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1000</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    QUERY_CAPTURE_MODE</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> AUTO</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查找性能回归的查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#D19A66;">    qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_id</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    qt</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_sql_text</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    rp</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> RegressedPlanId,</span></span>
<span class="line"><span style="color:#D19A66;">    fp</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> ForcedPlanId,</span></span>
<span class="line"><span style="color:#D19A66;">    rs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_duration</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> RegressedDuration,</span></span>
<span class="line"><span style="color:#D19A66;">    fs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_duration</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> ForcedDuration</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_store_query</span><span style="color:#ABB2BF;"> qs</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_store_query_text</span><span style="color:#ABB2BF;"> qt </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_text_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> qt</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_text_id</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_store_plan</span><span style="color:#ABB2BF;"> rp </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> rp</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_id</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_store_runtime_stats</span><span style="color:#ABB2BF;"> rs </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> rp</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> rs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span></span>
<span class="line"><span style="color:#C678DD;">CROSS</span><span style="color:#C678DD;"> APPLY</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 1</span><span style="color:#D19A66;"> p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_duration</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_store_plan</span><span style="color:#ABB2BF;"> p</span></span>
<span class="line"><span style="color:#C678DD;">    JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_store_runtime_stats</span><span style="color:#ABB2BF;"> s </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#D19A66;"> p</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_id</span></span>
<span class="line"><span style="color:#C678DD;">    ORDER BY</span><span style="color:#D19A66;"> s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_duration</span><span style="color:#C678DD;"> ASC</span></span>
<span class="line"><span style="color:#ABB2BF;">) fp (plan_id, avg_duration)</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_store_runtime_stats</span><span style="color:#ABB2BF;"> fs </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> fp</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> fs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_id</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> rs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_duration</span><span style="color:#56B6C2;"> &gt;</span><span style="color:#D19A66;"> fs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_duration</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 回归超过5倍</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 强制使用特定执行计划</span></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#ABB2BF;"> sp_query_store_force_plan </span><span style="color:#E06C75;">@query_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 42</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">@plan_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 108</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 取消强制计划</span></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#ABB2BF;"> sp_query_store_unforce_plan </span><span style="color:#E06C75;">@query_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 42</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">@plan_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 108</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="七、缺失索引-dmv" tabindex="-1"><a class="header-anchor" href="#七、缺失索引-dmv"><span>七、缺失索引 DMV</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- SQL Server 自动建议的缺失索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"><span style="color:#56B6C2;">    ROUND</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_total_user_cost</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_user_impact</span><span style="color:#ABB2BF;"> * (</span><span style="color:#D19A66;">migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">user_seeks</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">user_scans</span><span style="color:#ABB2BF;">), </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> ImprovementMeasure,</span></span>
<span class="line"><span style="color:#D19A66;">    mid</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> TableName,</span></span>
<span class="line"><span style="color:#D19A66;">    mid</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">equality_columns</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    mid</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">inequality_columns</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    mid</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">included_columns</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">user_seeks</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">user_scans</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_total_user_cost</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_user_impact</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_db_missing_index_details</span><span style="color:#ABB2BF;"> mid</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_db_missing_index_groups</span><span style="color:#ABB2BF;"> mig </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> mid</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">index_handle</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> mig</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">index_handle</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_db_missing_index_group_stats</span><span style="color:#ABB2BF;"> migs </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> mig</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">index_group_handle</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">group_handle</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> ImprovementMeasure </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 生成创建索引语句</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#98C379;">    &#39;CREATE INDEX IX_&#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">REPLACE</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">REPLACE</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">COALESCE</span><span style="color:#ABB2BF;">(equality_columns, </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#ABB2BF;">) +</span></span>
<span class="line"><span style="color:#C678DD;">        CASE</span><span style="color:#C678DD;"> WHEN</span><span style="color:#ABB2BF;"> equality_columns </span><span style="color:#C678DD;">IS NOT NULL</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> inequality_columns </span><span style="color:#C678DD;">IS NOT NULL</span><span style="color:#C678DD;"> THEN</span><span style="color:#98C379;"> &#39;_&#39;</span><span style="color:#C678DD;"> ELSE</span><span style="color:#98C379;"> &#39;&#39;</span><span style="color:#C678DD;"> END</span><span style="color:#ABB2BF;"> +</span></span>
<span class="line"><span style="color:#56B6C2;">        COALESCE</span><span style="color:#ABB2BF;">(inequality_columns, </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;,&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;_&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39; &#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#ABB2BF;">) +</span></span>
<span class="line"><span style="color:#98C379;">    &#39; ON &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#C678DD;">statement</span><span style="color:#ABB2BF;"> +</span></span>
<span class="line"><span style="color:#98C379;">    &#39; INCLUDE (&#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">COALESCE</span><span style="color:#ABB2BF;">(included_columns, </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#ABB2BF;">) + </span><span style="color:#98C379;">&#39;)&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> CreateIndexSQL</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_db_missing_index_details</span><span style="color:#ABB2BF;"> mid</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_db_missing_index_groups</span><span style="color:#ABB2BF;"> mig </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> mid</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">index_handle</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> mig</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">index_handle</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_db_missing_index_group_stats</span><span style="color:#ABB2BF;"> migs </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> mig</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">index_group_handle</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">group_handle</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_total_user_cost</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">avg_user_impact</span><span style="color:#ABB2BF;"> * (</span><span style="color:#D19A66;">migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">user_seeks</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">migs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">user_scans</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">缺失索引建议的局限</p><ol><li>不考虑索引维护成本（写入开销）</li><li>多个建议可能有重叠</li><li>建议的索引可能太大（INCLUDE 列太多）</li><li>需要人工审查后决定是否创建</li><li>实例重启后 DMV 数据清零</li></ol></div><hr><h2 id="八、实战-找到最慢的查询" tabindex="-1"><a class="header-anchor" href="#八、实战-找到最慢的查询"><span>八、实战：找到最慢的查询</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 找到 CPU 最高的查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_worker_time / execution_count </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> AvgCpuMicroseconds,</span></span>
<span class="line"><span style="color:#ABB2BF;">    execution_count,</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_worker_time / </span><span style="color:#D19A66;">1000000</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> TotalCpuSeconds,</span></span>
<span class="line"><span style="color:#56B6C2;">    SUBSTRING</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">st</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">text</span><span style="color:#ABB2BF;">, (</span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_start_offset</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) + </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">        (</span><span style="color:#C678DD;">CASE</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_end_offset</span><span style="color:#C678DD;"> WHEN</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> THEN</span><span style="color:#56B6C2;"> DATALENGTH</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">st</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">text</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">         ELSE</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_end_offset</span><span style="color:#C678DD;"> END</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_start_offset</span><span style="color:#ABB2BF;">) / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> QueryText,</span></span>
<span class="line"><span style="color:#D19A66;">    qp</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query_plan</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_exec_query_stats</span><span style="color:#ABB2BF;"> qs</span></span>
<span class="line"><span style="color:#C678DD;">CROSS</span><span style="color:#C678DD;"> APPLY</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_exec_sql_text</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">sql_handle</span><span style="color:#ABB2BF;">) st</span></span>
<span class="line"><span style="color:#C678DD;">CROSS</span><span style="color:#C678DD;"> APPLY</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_exec_query_plan</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">plan_handle</span><span style="color:#ABB2BF;">) qp</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> AvgCpuMicroseconds </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 找到逻辑读取最多的查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_logical_reads / execution_count </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> AvgLogicalReads,</span></span>
<span class="line"><span style="color:#ABB2BF;">    execution_count,</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_logical_reads </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> TotalLogicalReads,</span></span>
<span class="line"><span style="color:#56B6C2;">    SUBSTRING</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">st</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">text</span><span style="color:#ABB2BF;">, (</span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_start_offset</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) + </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">        (</span><span style="color:#C678DD;">CASE</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_end_offset</span><span style="color:#C678DD;"> WHEN</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> THEN</span><span style="color:#56B6C2;"> DATALENGTH</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">st</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">text</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">         ELSE</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_end_offset</span><span style="color:#C678DD;"> END</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_start_offset</span><span style="color:#ABB2BF;">) / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> QueryText</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_exec_query_stats</span><span style="color:#ABB2BF;"> qs</span></span>
<span class="line"><span style="color:#C678DD;">CROSS</span><span style="color:#C678DD;"> APPLY</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_exec_sql_text</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">sql_handle</span><span style="color:#ABB2BF;">) st</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> AvgLogicalReads </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 找到执行时间最长的查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_elapsed_time / execution_count / </span><span style="color:#D19A66;">1000</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> AvgDurationMs,</span></span>
<span class="line"><span style="color:#ABB2BF;">    execution_count,</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_elapsed_time / </span><span style="color:#D19A66;">1000</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> TotalElapsedMs,</span></span>
<span class="line"><span style="color:#56B6C2;">    SUBSTRING</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">st</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">text</span><span style="color:#ABB2BF;">, (</span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_start_offset</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) + </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">        (</span><span style="color:#C678DD;">CASE</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_end_offset</span><span style="color:#C678DD;"> WHEN</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> THEN</span><span style="color:#56B6C2;"> DATALENGTH</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">st</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">text</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">         ELSE</span><span style="color:#D19A66;"> qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_end_offset</span><span style="color:#C678DD;"> END</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statement_start_offset</span><span style="color:#ABB2BF;">) / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> QueryText</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_exec_query_stats</span><span style="color:#ABB2BF;"> qs</span></span>
<span class="line"><span style="color:#C678DD;">CROSS</span><span style="color:#C678DD;"> APPLY</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dm_exec_sql_text</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">qs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">sql_handle</span><span style="color:#ABB2BF;">) st</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> AvgDurationMs </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="九、面试技巧" tabindex="-1"><a class="header-anchor" href="#九、面试技巧"><span>九、面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频考点</p><ol><li><strong>Seek vs Scan</strong>：Seek 是查找（快），Scan 是扫描（慢），理解何时发生</li><li><strong>Key Lookup</strong>：非聚集索引未覆盖查询时回表，消除方法是 INCLUDE 列</li><li><strong>三种 Join 算子</strong>：Nested Loop（小×大+索引）、Hash（大×大）、Merge（已排序）</li><li><strong>参数嗅探</strong>：定义、影响、4 种解决策略</li><li><strong>Query Store</strong>：强制计划、回归检测，2016+ 推荐功能</li><li><strong>逻辑读取</strong>：调优最核心的指标，不受缓存影响</li><li><strong>缺失索引 DMV</strong>：SQL Server 自动建议索引，但要人工审查</li></ol></div><div class="hint-container warning"><p class="hint-container-title">易错点</p><ul><li>&quot;估算计划和实际计划一样&quot;——❌，行数估算偏差可能导致错误的算子选择</li><li>&quot;Hash Join 一定比 Nested Loop 慢&quot;——❌，大数据量无索引时 Hash 最优</li><li>&quot;Query Store 只能看不能操作&quot;——❌，可以强制计划和回退</li><li>&quot;参数嗅探一定是坏事&quot;——❌，大部分情况下参数嗅探提高了计划复用率</li></ul></div><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://learn.microsoft.com/en-us/sql/relational-databases/performance/execution-plans" target="_blank" rel="noopener noreferrer">Execution Plans</a></li><li><a href="https://learn.microsoft.com/en-us/sql/relational-databases/query-processing-architecture-guide" target="_blank" rel="noopener noreferrer">Query Processing Architecture Guide</a></li><li><a href="https://learn.microsoft.com/en-us/sql/relational-databases/performance/monitoring-performance-by-using-the-query-store" target="_blank" rel="noopener noreferrer">Query Store</a></li><li><a href="https://learn.microsoft.com/en-us/sql/relational-databases/system-dynamic-management-views/sys-dm-db-missing-index-details-transact-sql" target="_blank" rel="noopener noreferrer">Missing Index DMVs</a></li></ul>`,19)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};